// ============================================================

void effectRainbowStripe() {

  uint8_t hue =
    millis() / max(
      1,
      300 - speedValue
    );

  for (int i = 0; i < NUM_LEDS; i++) {

    leds[i] =
      ColorFromPalette(
        RainbowStripeColors_p,
        hue + i * 10,
        255
      );
  }
}

// ============================================================
// FIRE
// ============================================================

void effectFire() {

  static byte heat[NUM_LEDS];

  uint8_t cooling =
    map(
      speedValue,
      1,
      255,
      100,
      25
    );

  uint8_t sparking =
    map(
      speedValue,
      1,
      255,
      40,
      100
    );

  for (int i = 0; i < NUM_LEDS; i++) {

    heat[i] =
      qsub8(
        heat[i],
        random8(
          0,
          ((cooling * 10) / NUM_LEDS) + 2
        )
      );
  }

  for (
    int k = NUM_LEDS - 1;
    k >= 2;
    k--
  ) {

    heat[k] =
      (
        heat[k - 1] +
        heat[k - 2] +
        heat[k - 2]
      ) / 3;
  }

  if (
    random8() <
    sparking
  ) {

    int y =
      random8(
        min(
          7,
          NUM_LEDS
        )
      );

    heat[y] =
      qadd8(
        heat[y],
        random8(
          160,
          255
        )
      );
  }

  for (int j = 0; j < NUM_LEDS; j++) {

    leds[j] =
      ColorFromPalette(
        paletteArr[paletteIndex],
        heat[j],
        255
      );
  }
}

