  uint8_t level =
    beatsin8(
      max(
        1,
        map(
          speedValue,
          1,
          255,
          3,
          40
        )
      ),
      20,
      255
    );

  CRGB color(
    staticR,
    staticG,
    staticB
  );

  color.nscale8_video(level);

  fill_solid(
    leds,
    NUM_LEDS,
    color
  );
}

// ============================================================
// RUNNING
// ============================================================

void effectRunning() {

  fadeToBlackBy(
    leds,
    NUM_LEDS,
    40
  );

  uint8_t pos =
    beatsin8(
      map(
        speedValue,
        1,
        255,
        3,
        40
      ),
      0,
      NUM_LEDS - 1
    );

  leds[pos] =
    ColorFromPalette(
      paletteArr[paletteIndex],
      pos * 8
    );
}

// ============================================================
// COMET
// ============================================================

void effectComet() {

  fadeToBlackBy(
    leds,
    NUM_LEDS,
    map(
      speedValue,
      1,
      255,
      10,
      45
    )
  );

  uint16_t pos =
    beatsin16(
      map(
        speedValue,
        1,
        255,
        3,
        80
      ),
      0,
      NUM_LEDS - 1
    );

  leds[pos] =
    ColorFromPalette(
      paletteArr[paletteIndex],
      pos * 5,
      255
    );
}

// ============================================================
// METEOR
// ============================================================

void effectMeteor() {

  fadeToBlackBy(
    leds,
    NUM_LEDS,
    25
  );

  uint16_t pos =
    beatsin16(
      map(
        speedValue,
        1,
        255,
        2,
        50
      ),
      0,
      NUM_LEDS - 1
    );

  leds[pos] =
    CRGB::White;

  if (pos > 0)
    leds[pos - 1] =
      CRGB(
        180,
        180,
        180
      );

  if (pos > 1)
    leds[pos - 2] =
      CRGB(
        80,
        80,
        80
      );
}

// ============================================================
// TWINKLE
// ============================================================

void effectTwinkle() {

  fadeToBlackBy(
    leds,
    NUM_LEDS,
    35
  );

  if (
    random8(
      0,
      100
    ) <
    map(
      speedValue,
      1,
      255,
      3,
      30
    )
  ) {

    int pos =
      random16(
        NUM_LEDS
      );

    leds[pos] =
      ColorFromPalette(
        paletteArr[paletteIndex],
        random8()
      );
  }
}

// ============================================================
// POLICE
// ============================================================

void effectPolice() {

  uint32_t phase =
    millis() /
    max(
      10,
      255 - speedValue
    );

  bool red =
    (phase % 2) == 0;

  for (int i = 0; i < NUM_LEDS; i++) {

    if (i < NUM_LEDS / 2) {

      leds[i] =
        red
        ? CRGB::Red
        : CRGB::Blue;

    } else {

      leds[i] =
        red
        ? CRGB::Blue
        : CRGB::Red;
    }
  }
}

// ============================================================
// STROBE
// ============================================================

void effectStrobe() {

  uint16_t period =
    map(
      speedValue,
      1,
      255,
      1000,
      30
    );

  if (
    (millis() / period) % 2
  ) {

    fill_solid(
      leds,
      NUM_LEDS,
      CRGB(
        staticR,
        staticG,
        staticB
      )
    );

  } else {

    FastLED.clear();
  }
}

// ============================================================
// CONFETTI
// ============================================================

void effectConfetti() {

  fadeToBlackBy(
    leds,
    NUM_LEDS,
    10
  );

  if (
    random8(
      100
    ) <
    map(
      speedValue,
      1,
      255,
      5,
      50
    )
  ) {

    int pos =
      random16(
        NUM_LEDS
      );

    leds[pos] +=
      CHSV(
        random8(),
        255,
        255
      );
  }
}

// ============================================================
// EFFECT CONTROLLER
// ============================================================

void runEffect() {

  switch (effect) {

    case EFFECT_STATIC:
      effectStatic();
      break;

    case EFFECT_RAINBOW:
      effectRainbow();
      break;

    case EFFECT_RAINBOW_STRIPE:
      effectRainbowStripe();
      break;

    case EFFECT_FIRE:
      effectFire();
      break;

    case EFFECT_LAVA:
      effectPaletteNoise();
      break;

    case EFFECT_OCEAN:
      effectOcean();
      break;

    case EFFECT_FOREST:
      effectForest();
      break;

    case EFFECT_PARTY:
      effectParty();
      break;

    case EFFECT_AURORA:
      effectAurora();
      break;

    case EFFECT_PLASMA:
      effectPlasma();
      break;

    case EFFECT_CYBERPUNK:
      effectCyberpunk();
      break;

    case EFFECT_BREATHING:
      effectBreathing();
      break;

    case EFFECT_RUNNING:
      effectRunning();
      break;

    case EFFECT_COMET:
      effectComet();
      break;

    case EFFECT_METEOR:
      effectMeteor();
      break;

    case EFFECT_TWINKLE:
      effectTwinkle();
      break;

    case EFFECT_POLICE:
      effectPolice();
      break;

    case EFFECT_STROBE:
      effectStrobe();
      break;

    case EFFECT_CONFETTI:
      effectConfetti();
      break;

    default:
      effectStatic();
      break;
  }
}

// ============================================================
// WEB: ROOT
// ============================================================

void handleRoot() {

  String page =
    MAIN_PAGE;

  String effects;

  for (
    int i = 0;
    i < EFFECT_COUNT;
    i++
  ) {

    effects +=
      "<option value=\"" +
      String(i) +
      "\">" +
      effectNames[i] +
      "</option>";
  }

  page.replace(
    "%EFFECTS%",
    effects
  );

  String palettes;

  for (
    int i = 0;
    i < PALETTE_COUNT;
    i++
  ) {

    palettes +=
      "<option value=\"" +
      String(i) +
      "\">" +
      paletteNames[i] +
      "</option>";
  }

  page.replace(
    "%PALETTES%",
    palettes
  );

  server.send(
    200,
    "text/html",
    page
  );
}

// ============================================================
// POWER
// ============================================================

void handlePower() {

  powerState =
    !powerState;

  if (!powerState) {

    FastLED.clear();
    FastLED.show();

  } else {

    runEffect();
    FastLED.show();
  }

  saveSettings();

  server.send(
    200,
    "text/plain",
    "OK"
  );
}

// ============================================================
// BRIGHTNESS
// ============================================================

void handleBrightness() {

  if (
    server.hasArg("v")
  ) {

    brightness =
      constrain(
        server.arg("v").toInt(),
        1,
        MAX_BRIGHTNESS
      );

    FastLED.setBrightness(
      brightness
    );

    saveSettings();
  }

  server.send(
    200,
    "text/plain",
    "OK"
  );
}

