// COLOR
// ============================================================

void handleColor() {

  if (
    server.hasArg("r") &&
    server.hasArg("g") &&
    server.hasArg("b")
  ) {

    staticR =
      constrain(
        server.arg("r").toInt(),
        0,
        255
      );

    staticG =
      constrain(
        server.arg("g").toInt(),
        0,
        255
      );

    staticB =
      constrain(
        server.arg("b").toInt(),
        0,
        255
      );

    effect =
      EFFECT_STATIC;

    saveSettings();
  }

  server.send(
    200,
    "text/plain",
    "OK"
  );
}

// ============================================================
// SETUP
// ============================================================

void setup() {

  Serial.begin(
    115200
  );

  delay(500);

  Serial.println();
  Serial.println(
    "DeskLight starting..."
  );

  // ----------------------------------------------------------
  // LED
  // ----------------------------------------------------------

  FastLED.addLeds<
    LED_TYPE,
    LED_PIN,
    COLOR_ORDER
  >(
    leds,
    NUM_LEDS
  );

  FastLED.setBrightness(
    brightness
  );

  FastLED.setMaxPowerInVoltsAndMilliamps(
    5,
    4500
  );

  FastLED.clear();
  FastLED.show();

  // ----------------------------------------------------------
  // SETTINGS
  // ----------------------------------------------------------

  loadSettings();

  FastLED.setBrightness(
    brightness
  );

  // ----------------------------------------------------------
  // WIFI AP
  // ----------------------------------------------------------

  WiFi.mode(
    WIFI_AP
  );

  WiFi.softAP(
    AP_SSID,
    AP_PASS
  );

  IPAddress ip =
    WiFi.softAPIP();

  Serial.println();
  Serial.println(
    "WiFi AP started"
  );

  Serial.print(
    "SSID: "
  );

  Serial.println(
    AP_SSID
  );

  Serial.print(
    "Password: "
  );

  Serial.println(
    AP_PASS
  );

  Serial.print(
    "Open: http://"
  );

  Serial.println(
    ip
  );

  // ----------------------------------------------------------
  // SERVER
  // ----------------------------------------------------------

  server.on(
    "/",
    handleRoot
  );

  server.on(
    "/power",
    handlePower
  );

  server.on(
    "/brightness",
    handleBrightness
  );

  server.on(
    "/speed",
    handleSpeed
  );

  server.on(
    "/effect",
    handleEffect
  );

  server.on(
    "/palette",
    handlePalette
  );

  server.on(
    "/color",
    handleColor
  );

  server.begin();

  Serial.println(
    "HTTP server started"
  );

  // ----------------------------------------------------------
  // INITIAL EFFECT
  // ----------------------------------------------------------

  if (!powerState) {

    FastLED.clear();

  } else {

    runEffect();
  }

  FastLED.show();
}

// ============================================================
// LOOP
// ============================================================

void loop() {

  server.handleClient();

  if (powerState) {

    runEffect();

    FastLED.setBrightness(
      brightness
    );

    FastLED.show();
  }

  delay(10);
}
